// Finish: grain, a white frame and a photo credit, drawn on the Proof and the full-resolution export.
t3template.addControl({ id: 'grain', label: 'Grain', type: 'slider', min: 0, max: 0.4, step: 0.01, default: 0, panel: 'Finish' });
t3template.addControl({ id: 'frame', label: 'Frame', type: 'toggle', default: false, panel: 'Finish' });
t3template.addControl({ id: 'credit', label: 'Credit', type: 'text', placeholder: 'Photo credit', default: '', panel: 'Finish' });
t3template.addImageStage('finish', ({ context, width, height, scale, random }, c) => {
  if (c.grain > 0) {
    const rnd = random('grain');
    const px = context.getImageData(0, 0, width, height);
    const d = px.data;
    for (let i = 0; i < d.length; i += 4) {
      const n = (rnd() - 0.5) * 255 * c.grain;
      d[i] += n;
      d[i + 1] += n;
      d[i + 2] += n;
    }
    context.putImageData(px, 0, 0);
  }
  if (c.frame) {
    const m = 40 * scale;
    context.lineWidth = 6 * scale;
    context.strokeStyle = 'rgba(255, 255, 255, 0.9)';
    context.strokeRect(m, m, width - 2 * m, height - 2 * m);
  }
  if (c.credit) {
    context.font = `500 ${Math.round(22 * scale)}px system-ui, sans-serif`;
    context.fillStyle = 'rgba(255, 255, 255, 0.85)';
    context.textBaseline = 'bottom';
    context.fillText(c.credit, 64 * scale, height - 64 * scale);
  }
});
t3template.addToolbarButton('Clear Finish', () => t3template.setValues({ controls: { grain: 0, frame: false, credit: '' } }, 'Clear Finish'), { title: 'Reset grain, frame and credit' });
